ST.xhtml:
// === IMPLEMENTATION ===

{region "§1 Repli image reelle banc desactive"}
IF NOT Enable THEN
    // 🔌 Banc désactivé : repli sur l'image réelle, aucune simulation en cours
    KoboldMeasureEnablePrevious := FALSE;
    KoboldAutoEpisodeActive := FALSE;
    instKoboldPowerUpTimer(IN := FALSE);
    Ready       := FALSE;
    Busy        := FALSE;
    Done        := FALSE;
    Winch       := HwReal.Winch;
    Translation := HwReal.Translation;
    Operator    := HwReal.Operator;
    Machine     := HwReal.Machine;
    RETURN;
END_IF;

// ▶️ Banc actif : le cycle de simulation démarre pour ce scan.
// 🔒 Le comptage brut M1/M2 (`_SimEncoderRawPosM1`/`M2`, GVL_PERSISTENT) n'est JAMAIS réécrit ici :
//    `FB_Sim_Encoder` en reste le producteur unique (accumulation signée / preset). L'origine de banc
//    plausible vient de l'initialisation DÉCLARÉE `GVL_PERSISTENT` (1 000 000 pts), pas d'une
//    réinjection conditionnelle : un 0 lu ici n'est PAS une mémoire vierge, c'est un point de passage
//    légitime du compteur SIGNÉ. Le banc ne réécrit donc aucune mémoire codeur, pas même pour
//    « initialiser » une valeur lue à 0 — une telle réinjection (1 100 000 pts = 268,55 m de position
//    publiée en un seul scan, sans mouvement ni défaut et référence de homing conservée)
//    transformerait un zéro réel en téléportation de position.
Ready := TRUE;
Busy  := TRUE;
Done  := FALSE;


{endregion}

{region "§2 Simulation treuils M1/M2"}
// ── 1. MODÈLE TREUILS (M1 + M2) ─────────────────────────────────────────────
// Presets codeurs : déclenchés si PresetTriggerCmd = 2
M1_PresetCmd := (M1_PresetTriggerCmd = 2);
M2_PresetCmd := (M2_PresetTriggerCmd = 2);
WinchSpeedReportTauEffectiveS := SEL(SimWinchDynamicsActive, 0.0, SimWinchSpeedReportTauS);
WinchBrakeOpenDelayEffectiveS := SEL(SimWinchDynamicsActive, 0.0, SimWinchBrakeOpenDelayS);
WinchBrakeCloseDelayEffectiveS := SEL(SimWinchDynamicsActive, 0.0, SimWinchBrakeCloseDelayS);

// Conversions d'injection d'écart synchro (0.5m -> points codeur avec 8192 pts/tour, 2m/tour)
// 1m = 4096 points codeur.
M1_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);
M2_OffsetPts := REAL_TO_DINT(SimSyncDeviationOffset_M * 4096.0);

// Une plongée auto fige ses réglages avant l'arrêt : modifier l'IHM pendant AX5..AX8
// ne crée ni faux front fond ni changement de roulis en cours de mouvement.
IF KoboldMeasureEnable AND NOT KoboldMeasureEnablePrevious THEN
    KoboldAutoEpisodeActive := SimKoboldAutoModeActive;
    KoboldAutoDepthEpisode_M := SimKoboldAutoDepth_M;
    KoboldPowerUpEpisodeTime := SimKoboldPowerUpTime;
END_IF;
KoboldMeasureEnablePrevious := KoboldMeasureEnable;

// Instance modèle codeur M1
instSimEncoderM1(
    Enable           := TRUE,
    RelayFwd         := M1_RelayFwd,
    RelayRev         := M1_RelayRev,
    StepNumber       := M1_StepNumber,
    PresetCmd        := M1_PresetCmd,
    PresetValue      := M1_PresetValueOut,
    SpeedScaleFactor := SimEncoderSpeedFactor,
    CoastDistanceM   := SimWinchCoast_M,
    SpeedReportTauS  := WinchSpeedReportTauEffectiveS,
    TestOffsetCmd    := SimSyncDeviationInjectM1,
    TestOffsetPts    := M1_OffsetPts,
    RawPos           := RawPosM1
);

// T317 exploratoire -- electrique+charge+couplage M1/M2, diagnostic seul (Winch.* metier deja
// consomme via M2_TensionedCable_DI ci-dessous). Couplage/charge cables sur stimuli de banc en
// attente des signaux reels amont (CoupledBoth, benne au sol) -- cf. registre PLAN_T317.
instWinchElectricalM1(
    Enable                := Enable AND SimWinchElectricalDiagnosticsActive,
    StepCmd               := MAX(1, M1_StepNumber),
    DirectionCmd          := SEL(M1_RelayRev, 1, -1),
    NetworkVoltageAct_V   := 400.0,
    LoadFrac_Ratio         := SEL(SimBucketJamActive, SimWinchLoadFrac_Ratio, CST_SimBucketJamLoadFrac_Ratio),
    IsBucketGrounded      := KoboldBottomTouchPrev_DI,
    IsCoupledToPeer        := SimWinchCoupledActive,
    PeerTorque_Nm          := PeerTorqueM2Prev_Nm,
    PeerSpeed_Rpm          := PeerSpeedM2Prev_Rpm
);
IF SimWinchElectricalDiagnosticsActive THEN
    MotorTorqueM1_Nm := instWinchElectricalM1.MotorTorque_Nm;
    MotorIsStalledM1 := instWinchElectricalM1.IsStalled;
    PeerTorqueM1Prev_Nm := instWinchElectricalM1.MotorTorque_Nm;
    PeerSpeedM1Prev_Rpm := instWinchElectricalM1.SpeedAct_Rpm;
ELSE
    MotorTorqueM1_Nm := 0.0;
    MotorIsStalledM1 := FALSE;
    PeerTorqueM1Prev_Nm := 0.0;
    PeerSpeedM1Prev_Rpm := 0.0;
END_IF;

instWinchElectricalM2(
    Enable                := Enable AND SimWinchElectricalDiagnosticsActive,
    StepCmd               := MAX(1, M2_StepNumber),
    DirectionCmd          := SEL(M2_RelayRev, 1, -1),
    NetworkVoltageAct_V   := 400.0,
    LoadFrac_Ratio         := SEL(SimBucketJamActive, SimWinchLoadFrac_Ratio, CST_SimBucketJamLoadFrac_Ratio),
    IsBucketGrounded      := KoboldBottomTouchPrev_DI,
    IsCoupledToPeer        := SimWinchCoupledActive,
    PeerTorque_Nm          := PeerTorqueM1Prev_Nm,
    PeerSpeed_Rpm          := PeerSpeedM1Prev_Rpm
);
IF SimWinchElectricalDiagnosticsActive THEN
    MotorTorqueM2_Nm := instWinchElectricalM2.MotorTorque_Nm;
    MotorIsStalledM2 := instWinchElectricalM2.IsStalled;
    PeerTorqueM2Prev_Nm := instWinchElectricalM2.MotorTorque_Nm;
    PeerSpeedM2Prev_Rpm := instWinchElectricalM2.SpeedAct_Rpm;
ELSE
    MotorTorqueM2_Nm := 0.0;
    MotorIsStalledM2 := FALSE;
    PeerTorqueM2Prev_Nm := 0.0;
    PeerSpeedM2Prev_Rpm := 0.0;
END_IF;

// Détection coupure relais M2 pour renouveler la dispersion pseudo-aléatoire (±0.1m)
IF (M2_RelayFwdPrev AND NOT M2_RelayFwd) OR (M2_RelayRevPrev AND NOT M2_RelayRev) THEN
    // Générateur LCG 32-bit standard : X_{n+1} = (1103515245 * X_n + 12345) MOD 2^31
    RandomSeed := (RandomSeed * 1103515245 + 12345) AND 16#7FFFFFFF;
    // Dispersion pseudo-aléatoire entre -0.10 m et +0.10 m
    M2_EffectiveCoastM := SimWinchCoast_M + (UDINT_TO_REAL(RandomSeed MOD 2000) / 10000.0) - 0.10;
END_IF;
M2_RelayFwdPrev := M2_RelayFwd;
M2_RelayRevPrev := M2_RelayRev;

// Le FB codeur reste l'unique producteur de RawPosM2. Le ralentissement mesuré
// agit uniquement sur sa dynamique pendant une descente BOTH effectivement appliquée.
M2CoupledDescentActive := SimM2CoupledDescentModelActive
                          AND WinchBothDescentIntent
                          AND M1_RelayRev AND M2_RelayRev
                          AND NOT M1_RelayFwd AND NOT M2_RelayFwd;
M2EffectiveSpeedScaleFactor := SimEncoderSpeedFactor;
IF M2CoupledDescentActive THEN
    M2EffectiveSpeedScaleFactor := SimEncoderSpeedFactor * MAX(0.0, SimM2CoupledDescentFactor);
END_IF;

// Instance modèle codeur M2 (avec roulis et dispersion)
instSimEncoderM2(
    Enable           := TRUE,
    RelayFwd         := M2_RelayFwd,
    RelayRev         := M2_RelayRev,
    StepNumber       := M2_StepNumber,
    PresetCmd        := M2_PresetCmd,
    PresetValue      := M2_PresetValueOut,
    SpeedScaleFactor := M2EffectiveSpeedScaleFactor,
    CoastDistanceM   := M2_EffectiveCoastM,
    SpeedReportTauS  := WinchSpeedReportTauEffectiveS,
    TestOffsetCmd    := SimSyncDeviationInjectM2,
    TestOffsetPts    := M2_OffsetPts,
    RawPos           := RawPosM2
);

// L'épisode Kobold ne produit que la DI. Le cycle commande l'arrêt ; les FB codeurs
// conservent leur roulis historique après la retombée des relais.
IF NOT KoboldMeasureEnable AND NOT M1_RelayRev AND NOT M2_RelayRev
   AND NOT M1_RelayFwd AND NOT M2_RelayFwd THEN
    KoboldAutoEpisodeActive := FALSE;
END_IF;

// Recopie structures Winch simulées :
// 🛑 POLARITÉ DE FREIN SIMULÉ : 1 = contacteur commandé = frein OUVERT.
// Câblage réel : DI = 1 ⟺ frein OUVERT. Le modèle produit donc M1_BrakeIsOpen_DI := M1_BrakeCmd !
// Delai electrique/meca opt-in : SimWinchBrakeOpenDelayS/CloseDelayS=0.0 -> bascule le
// meme scan (comportement historique inchange, TC-P13-012). >0 -> retour retarde, sans jamais
// inverser la polarite (M1_BrakeIsOpenState suit toujours M1_BrakeCmd, juste avec latence).
IF M1_BrakeCmd THEN
    IF NOT M1_BrakeIsOpenState THEN
        M1_BrakeOpenTimerS := M1_BrakeOpenTimerS + CST_SimBenchCycleTimeS;
        IF M1_BrakeOpenTimerS >= MAX(0.0, WinchBrakeOpenDelayEffectiveS) THEN
            M1_BrakeIsOpenState := TRUE;
            M1_BrakeOpenTimerS := 0.0;
        END_IF;
    END_IF;
    M1_BrakeCloseTimerS := 0.0;
ELSE
    IF M1_BrakeIsOpenState THEN
        M1_BrakeCloseTimerS := M1_BrakeCloseTimerS + CST_SimBenchCycleTimeS;
        IF M1_BrakeCloseTimerS >= MAX(0.0, WinchBrakeCloseDelayEffectiveS) THEN
            M1_BrakeIsOpenState := FALSE;
            M1_BrakeCloseTimerS := 0.0;
        END_IF;
    END_IF;
    M1_BrakeOpenTimerS := 0.0;
END_IF;
Winch.M1_BrakeIsOpen_DI        := M1_BrakeIsOpenState;
// Retour UNIQUE « tous contacteurs retombés » = sens ET vitesse.
// Omettre les paliers ferait croire à l'arrêt pendant les transitoires → Méca A armée à tort.
Winch.M1_ContactorsReleased_DI := NOT (M1_RelayFwd OR M1_RelayRev
                                    OR M1_SpeedContactor_1 OR M1_SpeedContactor_2
                                    OR M1_SpeedContactor_3 OR M1_SpeedContactor_4);
Winch.M1_ThermalOk_DI          := TRUE; // Sauf panne simulée

IF M2_BrakeCmd THEN
    IF NOT M2_BrakeIsOpenState THEN
        M2_BrakeOpenTimerS := M2_BrakeOpenTimerS + CST_SimBenchCycleTimeS;
        IF M2_BrakeOpenTimerS >= MAX(0.0, WinchBrakeOpenDelayEffectiveS) THEN
            M2_BrakeIsOpenState := TRUE;
            M2_BrakeOpenTimerS := 0.0;
        END_IF;
    END_IF;
    M2_BrakeCloseTimerS := 0.0;
ELSE
    IF M2_BrakeIsOpenState THEN
        M2_BrakeCloseTimerS := M2_BrakeCloseTimerS + CST_SimBenchCycleTimeS;
        IF M2_BrakeCloseTimerS >= MAX(0.0, WinchBrakeCloseDelayEffectiveS) THEN
            M2_BrakeIsOpenState := FALSE;
            M2_BrakeCloseTimerS := 0.0;
        END_IF;
    END_IF;
    M2_BrakeOpenTimerS := 0.0;
END_IF;
Winch.M2_BrakeIsOpen_DI        := M2_BrakeIsOpenState;
Winch.M2_ContactorsReleased_DI := NOT (M2_RelayFwd OR M2_RelayRev
                                    OR M2_SpeedContactor_1 OR M2_SpeedContactor_2
                                    OR M2_SpeedContactor_3 OR M2_SpeedContactor_4);
Winch.M2_ThermalOk_DI          := TRUE;

// Cohérent avec M2_TensionedCable_DI (sain par défaut) : capteur TOP libre en simu,
// sauf stimulus manuel SimTopPositionActive (injection de fait capteur au banc).
Winch.M1M2_TopPositionFree_DI  := NOT SimTopPositionActive;
// Le Kobold ne deduit pas l'etat cable : seul le stimulus safety explicite injecte une panne.
Winch.M2_TensionedCable_DI     := NOT SimM2TensionedCableFaultInject;

Winch.COD1_PosValue            := instSimEncoderM1.RawPosOut;
Winch.COD1_SpdValue            := instSimEncoderM1.RawSpdOut;
Winch.COD1_Alarms              := 0;
Winch.COD1_Warnings            := 0;
Winch.COD1_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING (bus OK)

Winch.COD2_PosValue            := instSimEncoderM2.RawPosOut;
Winch.COD2_SpdValue            := instSimEncoderM2.RawSpdOut;
Winch.COD2_Alarms              := 0;
Winch.COD2_Warnings            := 0;
Winch.COD2_DeviceState         := DEVICE_STATE.RUNNING; // État device RUNNING

{region "§2bis Rattrapage mecanique M1/M2"}
// La benne relie mecaniquement les deux treuils. En MONTEE couplee et sans blocage, le jeu relatif
// est repris : Delta = PosM2 - PosM1 rejoint la BUTEE mecanique benne FERMEE (OffsetCloseM).
// Sans ce rattrapage, un ecart residuel (trou metier de fermeture : coupure d'anticipation a 13,8 m
// alors que l'etat ferme exige 14,0 m) laisse la benne "non fermee" et plafonne la montee au palier 1.
// 🔒 Le modele n'ecrit QUE l'image publiee (Winch.COD2_PosValue) -- JAMAIS RawPosM2, memoire
//    persistante du codeur dont FB_Sim_Encoder reste l'unique producteur.
// 🔒 MONTEE UNIQUEMENT : la descente couplee reste au modele existant SimM2CoupledDescentModelActive
//    (exclusion mutuelle : les deux modeles ne s'appliquent jamais ensemble).
// 🔒 Cible = BUTEE MECANIQUE benne fermee (BucketOffsetCloseM) : seule valeur qui fasse converger
//    l'ouverture benne vers 0 % ; une cible intermediaire laisse un ecart plancher jamais
//    corrigible. Le sens unique (correction seulement si Delta < cible) et le bornage de pente
//    (LIMIT + MIN(cible - Delta)) interdisent tout depassement de butee.
WinchCouplingBothSameDir := (M1_RelayFwd AND M2_RelayFwd) OR (M1_RelayRev AND M2_RelayRev);
WinchCouplingGate := SimWinchCouplingModelActive
                     AND WinchCouplingBothSameDir
                     AND M1_RelayFwd AND NOT M1_RelayRev        // montee uniquement
                     AND M1_BrakeIsOpenState AND M2_BrakeIsOpenState
                     AND Winch.M2_TensionedCable_DI            // cable tendu : sinon aucun effort transmis
                     AND NOT KoboldBottomTouchPrev_DI          // benne au fond : aucun mouvement reel
                     AND NOT (M1_PresetCmd OR M2_PresetCmd)    // jamais pendant un preset/homing
                     AND NOT SimBucketJamActive;               // mâchoires bloquees : aucun rattrapage
WinchCouplingActive := WinchCouplingGate;
WinchCouplingCorrectionPts := 0;
IF WinchCouplingGate THEN
    WinchCouplingDelta_M := M2_CablePos_M - M1_CablePos_M;
    // Cible = butee mecanique benne FERMEE (ecart relatif 0 %). Le sens unique et le bornage
    // de pente garantissent qu'aucune correction ne depasse cette butee.
    WinchCouplingTarget_M := BucketOffsetCloseM;
    IF WinchCouplingDelta_M < WinchCouplingTarget_M THEN
        WinchCouplingCorrection_M := (WinchCouplingTarget_M - WinchCouplingDelta_M)
                                     * CST_SimBenchCycleTimeS
                                     / (CST_SimWinchCouplingTauS + CST_SimBenchCycleTimeS);
        // Sens unique + bornage (§6) : jamais de saut, jamais au-dela de la cible
        WinchCouplingCorrection_M := LIMIT(0.0, WinchCouplingCorrection_M,
                                           MIN(CST_SimWinchCouplingStepMax_M,
                                               WinchCouplingTarget_M - WinchCouplingDelta_M));
        WinchCouplingCorrectionDInt := REAL_TO_DINT(WinchCouplingCorrection_M
                                                    * CST_SimWinchCouplingPtsPerM);
        IF WinchCouplingCorrectionDInt > 0 THEN
            WinchCouplingAccumPts := WinchCouplingAccumPts + WinchCouplingCorrectionDInt;
            WinchCouplingCorrectionPts := WinchCouplingCorrectionDInt;
        END_IF;
    END_IF;
ELSIF M2_RelayRev AND NOT M2_RelayFwd THEN
    // Ouverture commandee : la reprise de jeu est relachee (le cable de fermeture devide),
    // sinon l'image M2 masquerait l'ouverture reelle.
    WinchCouplingCorrectionDInt := REAL_TO_DINT(CST_SimWinchCouplingStepMax_M
                                                * CST_SimWinchCouplingPtsPerM);
    WinchCouplingAccumPts := MAX(0, WinchCouplingAccumPts - WinchCouplingCorrectionDInt);
END_IF;
// Un preset/homing rend la reference absolue : l'offset de reprise de jeu n'a plus de sens.
IF M1_PresetCmd OR M2_PresetCmd THEN
    WinchCouplingAccumPts := 0;
END_IF;
// Report sur l'IMAGE uniquement (le raw persistant n'est jamais touche), et seulement quand le
// modele est actif : en mode desactive, l'image reste strictement celle du codeur.
IF SimWinchCouplingModelActive AND (WinchCouplingAccumPts > 0) THEN
    Winch.COD2_PosValue := Winch.COD2_PosValue + DINT_TO_UDINT(WinchCouplingAccumPts);
END_IF;
{endregion}


{endregion}

{region "§3 Simulation translation M3"}
// ── 2. MODÈLE TRANSLATION M3 (AC600) ─────────────────────────────────────────
M3_RelayFwd := M3_ReqTremie AND NOT M3_ReqMaintenance;
M3_RelayRev := M3_ReqMaintenance AND NOT M3_ReqTremie;

instSimTranslation(
    Enable          := TRUE,
    ReqTremie       := M3_RelayFwd,
    ReqMaintenance  := M3_RelayRev,
    SpeedTgt_Pct    := M3_SpeedCmd_Pct,
    FullTravelTimeS := CST_M3FullTravelTimeS,
    BrakeReleaseCmd := M3_BrakeCmd,
    SensorIntermittenceActive := SimM3SensorIntermittenceActive,
    SensorStabilizationS := SimM3SensorStabilizationS,
    SensorElectricalDelayS := SimM3SensorElectricalDelayS,
    SensorIntermittencePeriodS := SimM3SensorIntermittencePeriodS,
    SensorHysteresis_M := SimM3SensorHysteresis_M,
    SensorLoadAngleTriggerRad := SimM3SensorLoadAngleTriggerRad,
    SensorScenarioSeed := SimM3SensorScenarioSeed,
    SensorBlipTransitions := SimM3SensorBlipTransitions,
    SensorBlipDurationS := SimM3SensorBlipDurationS,
    BrakeFaultCloseWhileRunning := SimM3BrakeFaultCloseWhileRunning,
    BrakeFaultCloseDelay_S := SimM3BrakeFaultCloseDelayS,
    EndStopRecoilMax_M := SimM3EndStopRecoilMax_M,
    LoadReactionGain_Mps2 := SimM3LoadReactionGain_Mps2
);
M3BrakeFaultCloseActive := instSimTranslation.BrakeFaultCloseActive;
M3SensorBlipActive := instSimTranslation.SensorBlipActive;

// Remplissage capteurs de position M3 : l'override manuel conserve exactement le
// même ordre que FB_Translation_PositionDecoder (bit4=Trémie ... bit0=Maintenance).
IF SimM3SensorsWordOverrideActive THEN
    Translation.M3_PosTremie_DI      := SimM3SensorsWord.4;
    Translation.M3_PosPV_DI          := SimM3SensorsWord.3;
    Translation.M3_PosPVP2_DI        := SimM3SensorsWord.2;
    Translation.M3_PosP1_DI          := SimM3SensorsWord.1;
    Translation.M3_PosMaintenance_DI := SimM3SensorsWord.0;
ELSE
    Translation.M3_PosTremie_DI      := instSimTranslation.PosTremie;
    Translation.M3_PosPV_DI          := instSimTranslation.PosPV;
    Translation.M3_PosPVP2_DI        := instSimTranslation.PosP2;
    Translation.M3_PosP1_DI          := instSimTranslation.PosP1;
    Translation.M3_PosMaintenance_DI := instSimTranslation.PosMaintenance;
END_IF;

// Retour auxiliaire du frein, distinct de la commande electrique.
Translation.M3_BrakeIsOpen_DI    := instSimTranslation.BrakeContactOpen;

// Thermique moteur/variateur AC600 — pas de panne simulée, toujours OK (comme Winch.M1/M2_ThermalOk_DI)
Translation.M3_ThermalOK_DI      := TRUE;

// Simulation StatusWord AC600 : Bit 0 (Power Ready) = 1, Bit 7 (Comm Ready) = 1 -> 16#0087 en mouvement
// Bit0 retombe à l'arrêt, cohérent avec un variateur qui confirme l'arrêt sans rester "actif" —
// FB_Safety_Translation lit ce bit comme indicateur "mouvement non commandé" (Méca B, TonMecaB 3s) :
// un Bit0 forcé à 1 en continu à l'arrêt déclencherait un PowerCutOff simulé permanent après 3s.
// DrivePowerReady (diagnostic IHM seul, non consommé par un interlock) est le seul autre lecteur,
// aucune régression de mouvement possible.
IF instSimTranslation.ActualFrequency_Hz > 0.5 THEN
    M3_StatusWordSim := 16#0087; // + Operating/Running
ELSE
    M3_StatusWordSim := 16#0080; // Comm Ready seul -- Bit0 retombé, arrêt confirmé
END_IF;
M3_ActualFreqHz := REAL_TO_UINT(instSimTranslation.ActualFrequency_Hz * 100.0);

Translation.M3_StatusWord        := M3_StatusWordSim;
Translation.M3_ActualFrequencyHz := M3_ActualFreqHz;
Translation.AC600_DeviceState    := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§4 Simulation operateur joystick"}
// ── 3. MODÈLE OPÉRATEUR / JOYSTICK ───────────────────────────────────────────
instSimJoystick(
    Enable              := TRUE,
    NeutralRaw          := 5000,
    MaxRaw              := 10000,
    BtnLeft_Rev_TREMIE  := SimJoystickLeft_Rev_TREMIE_Active,
    BtnRight_Fwd_MAINT  := SimJoystickRight_Fwd_MAINT_Active,
    BtnFwd_Up_Close     := SimJoystickFwd_Up_Close_Active,
    BtnRev_Down_Open    := SimJoystickRev_Down_Open_Active,
    OvershootActive     := SimJoystickOvershoot_Active,
    BagotementActive    := SimJoystickBagotement_Active,
    CycleTimeS          := 0.010
);

// Les boutons directionnels simplifient les essais : une commande unique impose
// une butée d'axe ; aucune commande ou une combinaison reste au neutre / stimulus avancé.
// Le modèle dynamique (montée/retombée/bagotement) pilote RawX/RawY dès qu'un bouton est actif.
SimJoystickDirectionCount := BOOL_TO_INT(SimJoystickLeft_Rev_TREMIE_Active)
                           + BOOL_TO_INT(SimJoystickRight_Fwd_MAINT_Active)
                           + BOOL_TO_INT(SimJoystickFwd_Up_Close_Active)
                           + BOOL_TO_INT(SimJoystickRev_Down_Open_Active);
IF (SimJoystickDirectionCount >= 1) OR instSimJoystick.ReturningActive THEN
    // Bouton(s) actif(s) OU retour dynamique en cours (retombée/bagotement) → sortie du modèle.
    // (≥2 boutons : le modèle gère lui-même le neutre — pas de diagonale implicite.)
    Operator.JoyXRaw_ANA1 := instSimJoystick.RawX;
    Operator.JoyYRaw_ANA2 := instSimJoystick.RawY;
ELSE
    // Modèle au repos → stimulus analogique avancé (mode « sans bouton »).
    Operator.JoyXRaw_ANA1 := SimJoystickRawX;
    Operator.JoyYRaw_ANA2 := SimJoystickRawY;
END_IF;

// Homme-mort : stimulus brut amont. En simulation avec boutons directionnels actifs,
// l'appui homme-mort est automatiquement inclus pour faciliter les essais sur banc.
Operator.JoyBtnRaw := SimJoystickRawButton OR (SimJoystickDirectionCount > 0);

Operator.CanBusState      := 2; // CANbusState 2 = ACTIVE
Operator.JOY1_DeviceState := DEVICE_STATE.RUNNING; // État device RUNNING


{endregion}

{region "§5 Simulation securite et image machine"}
// ── 4. MODÈLE SÉCURITÉ & COMMUNS MACHINE ─────────────────────────────────────
instSimSafety(
    Enable            := TRUE,
    SimChainOkBit     := SimChainOkBit,
    SimPhaseRotationOkBit := SimPhaseRotationOkBit,
    PowerCutOff_A     := PowerKeepAlive_A,
    PowerCutOff_B     := PowerKeepAlive_B,
    PowerCutOffRequest:= PowerCutOffRequest,
    EmergencyArming   := EmergencyArming_RQ,
    BtnEmergencyStop  := BtnEmergencyStop,
    TestCutActive     := TestCutActive
);

Machine.PowerContactorEngaged_DI   := instSimSafety.SimContactorOk;
Machine.EmergencyChainClosed_DI    := instSimSafety.SimChainOk;
Machine.PhaseRotationOk_DI          := instSimSafety.SimPhaseRotationOk;
Machine.M1_M2_M3_BrakeThermalOk_DI     := TRUE;
instKoboldPowerUpTimer(IN := KoboldAutoEpisodeActive AND KoboldMeasureEnable
                        AND (M1_CablePos_M > KoboldAutoDepthEpisode_M),
                        PT := KoboldPowerUpEpisodeTime);
IF KoboldAutoEpisodeActive THEN
    Machine.M1_M2_KoboldBottomTouch_DI := instKoboldPowerUpTimer.Q
                                           AND (M1_CablePos_M > KoboldAutoDepthEpisode_M);
ELSE
    Machine.M1_M2_KoboldBottomTouch_DI := SimKoboldContactValue;
END_IF;
// T317 : memorise pour le prochain scan -- reutilise le VRAI capteur fond (Kobold), pas un
// stimulus invente, cf. retour utilisateur 2026-09-18 (le capteur fond existe deja reel+sim).
KoboldBottomTouchPrev_DI := Machine.M1_M2_KoboldBottomTouch_DI;
Machine.HydraulicThermalOk_DI          := TRUE;
Machine.TremieFull_OR_GateRaised_DI    := FALSE; // Pas encore câblé, simulé inactif par défaut

// ✅ Cycle de simulation terminé : les 4 images sont publiées pour ce scan
Busy := FALSE;
Done := TRUE;

{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Encoder) ===

{region "§1 Gate"}
IF NOT Enable THEN
    RawPosOut := RawPos;
    // Comptage non evalue hors simulation : la saturation ne doit pas rester figee a TRUE.
    CountSaturated := FALSE;
    RETURN;
END_IF;
{endregion}

{region "§2 Injection test"}
// Injection test banc : VRAI saut de position (comme un glissement réel),
// pour tester Concept 1 / Méca E ET le rattrapage joystick (voir GVL_Simulation bandeau).
TestOffsetEdge(CLK := TestOffsetCmd);
IF TestOffsetEdge.Q THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + TestOffsetPts);
END_IF;
{endregion}

{region "§3 Comptage"}
// 🎚️ Vitesse simulée = interpolation linéaire du palier (palier 1 → MinSpeedMps, palier 5 → MaxSpeedMps),
// pas par pas de (Max−Min)/4. Palier 0 (arrêt) ramène au palier 1 mais aucun mouvement n'est
// appliqué tant que RelayFwd/RelayRev = FALSE (section plus bas).
EffStep  := MAX(StepNumber, 1);
SpeedMps := MinSpeedMps + (INT_TO_REAL(EffStep) - 1.0) * ((MaxSpeedMps - MinSpeedMps) / 4.0);
// Points par cycle = vitesse (m/s) × points par mètre × période tâche (s) × facteur confort.
Increment := REAL_TO_UDINT(SpeedMps * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev) * CycleTimeS * SpeedScaleFactor);
// Increment "lent" (palier 1) : vitesse du roulis inertiel apres coupure des relais.
IncrStep1 := REAL_TO_UDINT(MinSpeedMps * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev) * CycleTimeS * SpeedScaleFactor);

// Front du preset : lance la latence de referencement (le codeur réel n'est pas
// instantane — il met PresetLatencyCycles cycles a se re-referencer apres le front).
PresetEdge(CLK := PresetCmd);
IF PresetEdge.Q THEN
    PresetPending := TRUE;
    PresetCount := PresetLatencyCycles;
END_IF;

// 📐 Le comptage brut est un entier SIGNÉ 32 bits : le conteneur UDINT n'est qu'un support
// d'échange (toute la chaîne aval le relit via UDINT_TO_DINT : FB_Encoder_Scale, FB_Encoder_Homing).
// Sa valeur 0 n'est donc PAS une butée mécanique — c'est un point de passage comme un autre, et
// c'est la seule façon de rester fidèle à un codeur absolu, dont le zéro de comptage est arbitraire.
// Aucune branche de comptage ne borne donc à un littéral : seule la garde de plage §3bis intervient,
// et elle est signalée (CountSaturated).
// Pendant l'attente du preset, la position brute est conservee (le codeur n'a pas encore re-reference).
// Le mouvement est gelé pendant la latence, comme un codeur réel en cours de referencement.
IF PresetPending THEN
    IF PresetCount > 0 THEN
        PresetCount := PresetCount - 1;
    ELSE
        // Latence écoulée : applique la valeur cible du preset.
        RawPos := PresetValue;
        PresetPending := FALSE;
    END_IF;
    TargetSpeedMps := 0.0;
ELSIF RelayFwd THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + UDINT_TO_DINT(Increment));
    MovingDir := 1;
    CoastPtsLeft := CoastDistanceM * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
    TargetSpeedMps := SpeedMps;
ELSIF RelayRev THEN
    RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(Increment));
    MovingDir := -1;
    CoastPtsLeft := CoastDistanceM * (UDINT_TO_REAL(PointsPerRev) / CableM_PerRev);
    TargetSpeedMps := -SpeedMps;
ELSE
    // Relais coupes : roulis inertiel (anticipation d'arret mecanique). Le treuil
    // continue a vitesse palier 1 dans le dernier sens jusqu'a epuisement de CoastPtsLeft.
    IF (CoastPtsLeft >= 1.0) AND (MovingDir <> 0) THEN
        IF MovingDir = 1 THEN
            RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) + UDINT_TO_DINT(IncrStep1));
            TargetSpeedMps := MinSpeedMps;
        ELSE
            RawPos := DINT_TO_UDINT(UDINT_TO_DINT(RawPos) - UDINT_TO_DINT(IncrStep1));
            TargetSpeedMps := -MinSpeedMps;
        END_IF;
        CoastPtsLeft := CoastPtsLeft - UDINT_TO_REAL(IncrStep1);
    ELSE
        MovingDir := 0;
        CoastPtsLeft := 0.0;
        TargetSpeedMps := 0.0;
    END_IF;
END_IF;
{endregion}

{region "§3bis Garde de plage de comptage"}
// 🛑 SEULE borne du comptage : la plage de représentation signée. Elle est SIGNALÉE
// (CountSaturated) et cohérente — une position bornée ne publie plus de vitesse de mouvement,
// ce qui interdit la signature « position figée + vitesse non nulle + zéro défaut ».
CountSaturated := FALSE;
IF UDINT_TO_DINT(RawPos) > CST_CountTravelLimitPts THEN
    RawPos := DINT_TO_UDINT(CST_CountTravelLimitPts);
    CountSaturated := TRUE;
ELSIF UDINT_TO_DINT(RawPos) < -CST_CountTravelLimitPts THEN
    RawPos := DINT_TO_UDINT(-CST_CountTravelLimitPts);
    CountSaturated := TRUE;
END_IF;
IF CountSaturated THEN
    TargetSpeedMps := 0.0;
END_IF;
{endregion}

{region "§4 Sortie"}
RawPosOut := RawPos;
// Retour vitesse rapporte (RawSpdOut) : 1er ordre vers TargetSpeedMps. SpeedReportTauS=0.0
// -> alpha=1 -> saut instantane (comportement historique inchange).
ReportedSpeedMps := ReportedSpeedMps
    + (CycleTimeS / (SpeedReportTauS + CycleTimeS)) * (TargetSpeedMps - ReportedSpeedMps);
// Formule inverse vitesse brute EtherCAT CoE (0.1 RPM) :
// SpdValue = (V_mps * 60.0) / (0.1 * CableM_PerRev) = V_mps * 300.0 (sur tambour 2m)
IF (CableM_PerRev > 0.0) THEN
    RawSpdOut := REAL_TO_DINT((ReportedSpeedMps * 60.0) / (0.1 * CableM_PerRev) * SpeedScaleFactor);
ELSE
    RawSpdOut := 0;
END_IF;
{endregion}

// === IMPLEMENTATION (à coller dans le corps ST du POU FB_Sim_Joystick) ===

{region "§1 Gate"}
// 🔑 Initialise au neutre au premier cycle uniquement ; ensuite RawX/RawY sont pilotés
// dynamiquement par les boutons. Quand la simulation est coupée, on revient au neutre.
IF NOT Enable THEN
    FirstCycle := TRUE;
    State      := CST_ST_IDLE;
    RawX       := NeutralRaw;
    RawY       := NeutralRaw;
    RawButton  := FALSE;
    ReturningActive := FALSE; // 📊 Neutralisation : simulation inactive hors Enable
    RETURN;
END_IF;
{endregion}

{region "§2 Initialisation neutre"}
IF FirstCycle THEN
    RawX       := NeutralRaw;
    RawY       := NeutralRaw;
    RawButton  := FALSE;
    State      := CST_ST_IDLE;
    FirstCycle := FALSE;
END_IF;
{endregion}

{region "§3 Pseudo-aléatoire (bruit de montée)"}
// 🎲 Compteur qui repasse à zéro, multiplié pour rester dans la plage (méthode validée).
// Le bruit s'ajoute à la rampe de montée uniquement (pas à la retombée, linéaire propre).
RandCnt := (RandCnt + 1) MOD 1000;
Noise   := (RandCnt MOD 50) - 25;   // ±25 points (≈ ±0.5% de la course)
{endregion}

{region "§4 Cibles & transitions"}
// 🎯 Un SEUL bouton impose une butée d'axe ; 0 ou ≥2 boutons = neutre (pas de diagonale implicite).
// Si OvershootActive : la cible de montée DÉPASSE la butée (MaxRaw+AMT ou 0−AMT) pour
// déclencher le défaut capteur hors plage (RawOutOfRange) — test du dépassement de valeur.
BtnCount := BOOL_TO_INT(BtnLeft_Rev_TREMIE) + BOOL_TO_INT(BtnRight_Fwd_MAINT)
          + BOOL_TO_INT(BtnFwd_Up_Close) + BOOL_TO_INT(BtnRev_Down_Open);
IF BtnCount = 1 THEN
    IF BtnLeft_Rev_TREMIE THEN
        IF OvershootActive THEN TargetX := 0 - CST_OVERSHOOT_AMT; ELSE TargetX := 0; END_IF;
        TargetY := NeutralRaw; ActiveAxis := 1;
    ELSIF BtnRight_Fwd_MAINT THEN
        IF OvershootActive THEN TargetX := MaxRaw + CST_OVERSHOOT_AMT; ELSE TargetX := MaxRaw; END_IF;
        TargetY := NeutralRaw; ActiveAxis := 1;
    ELSIF BtnFwd_Up_Close THEN
        TargetX := NeutralRaw;
        IF OvershootActive THEN TargetY := MaxRaw + CST_OVERSHOOT_AMT; ELSE TargetY := MaxRaw; END_IF;
        ActiveAxis := 2;
    ELSE
        TargetX := NeutralRaw;
        IF OvershootActive THEN TargetY := 0 - CST_OVERSHOOT_AMT; ELSE TargetY := 0; END_IF;
        ActiveAxis := 2;
    END_IF;
    State := CST_ST_RISE;
ELSE
    // 0 ou ≥2 boutons : retour au neutre.
    TargetX := NeutralRaw;
    TargetY := NeutralRaw;
    IF State = CST_ST_RISE THEN
        // Front de relâchement : retour au neutre. D'abord retombée linéaire (FALL),
        // puis petit bagotement de quelques % autour du neutre si OvershootActive (voir §6).
        State := CST_ST_FALL;
    END_IF;
END_IF;
{endregion}

{region "§5 Ascending (rampe + bruit)"}
IF State = CST_ST_RISE THEN
    // Pas de montée : pleine course (MaxRaw−NeutralRaw) en RiseTimeS.
    RiseStep := INT_TO_REAL(MaxRaw - NeutralRaw) / (RiseTimeS / CycleTimeS);
    // Axe X
    IF RawX < TargetX THEN
        RawX := MIN(RawX + REAL_TO_INT(RiseStep) + Noise, TargetX);
    ELSIF RawX > TargetX THEN
        RawX := MAX(RawX - REAL_TO_INT(RiseStep) - Noise, TargetX);
    END_IF;
    // Axe Y
    IF RawY < TargetY THEN
        RawY := MIN(RawY + REAL_TO_INT(RiseStep) + Noise, TargetY);
    ELSIF RawY > TargetY THEN
        RawY := MAX(RawY - REAL_TO_INT(RiseStep) - Noise, TargetY);
    END_IF;
END_IF;
{endregion}

{region "§6 Retombée linéaire (sans bagotement)"}
IF State = CST_ST_FALL THEN
    // Pas de retombée : pleine course en FallTimeMs (TIME_TO_REAL → ms, /1000 → s).
    FallStep := INT_TO_REAL(MaxRaw - NeutralRaw) / (TIME_TO_REAL(FallTimeMs) / 1000.0 / CycleTimeS);
    IF RawX < NeutralRaw THEN
        RawX := MIN(RawX + REAL_TO_INT(FallStep), NeutralRaw);
    ELSIF RawX > NeutralRaw THEN
        RawX := MAX(RawX - REAL_TO_INT(FallStep), NeutralRaw);
    END_IF;
    IF RawY < NeutralRaw THEN
        RawY := MIN(RawY + REAL_TO_INT(FallStep), NeutralRaw);
    ELSIF RawY > NeutralRaw THEN
        RawY := MAX(RawY - REAL_TO_INT(FallStep), NeutralRaw);
    END_IF;
    IF RawX = NeutralRaw AND RawY = NeutralRaw THEN
        // Arrivée au neutre : si bagotement demandé, lance un petit balancement de quelques %.
        IF BagotementActive THEN
            State := CST_ST_OVERSHOOT;
            IF ActiveAxis = 1 THEN
                OscDev := INT_TO_REAL(CST_BAGOT_AMT);
            ELSE
                OscDev := INT_TO_REAL(CST_BAGOT_AMT);
            END_IF;
            OscVel := 0.0;
        ELSE
            State := CST_ST_IDLE;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§7 Bagotement (dépassement + oscillations amorties)"}
IF State = CST_ST_OVERSHOOT THEN
    // 🎢 Oscillateur harmonique amorti discret (semi-implicite) autour du neutre :
    // le joystick dépasse le centre (~12% de l'écart initial) puis oscille 1-2 fois
    // avant de se stabiliser — comportement d'un opérateur qui relâche et balance.
    OscAcc := -CST_OSC_K * OscDev - CST_OSC_C * OscVel;
    OscVel := OscVel + OscAcc;
    OscDev := OscDev + OscVel;
    IF ActiveAxis = 1 THEN
        RawX := NeutralRaw + REAL_TO_INT(OscDev);
    ELSE
        RawY := NeutralRaw + REAL_TO_INT(OscDev);
    END_IF;
    // Stabilisé : revient exactement au centre.
    IF ABS(OscDev) < 1.0 AND ABS(OscVel) < 1.0 THEN
        State := CST_ST_IDLE;
        IF ActiveAxis = 1 THEN
            RawX := NeutralRaw;
        ELSE
            RawY := NeutralRaw;
        END_IF;
    END_IF;
END_IF;
{endregion}

{region "§8 Homme-mort brut + drapeau retour"}
RawButton := BtnLeft_Rev_TREMIE OR BtnRight_Fwd_MAINT OR BtnFwd_Up_Close OR BtnRev_Down_Open;
// Drapeau "retour dynamique en cours" : TRUE si l'état est FALL ou OVERSHOOT (retombée/bagotement).
// Permet à FB_SimBench d'émettre la sortie du modèle même après relâchement du bouton.
ReturningActive := (State = CST_ST_FALL) OR (State = CST_ST_OVERSHOOT);
{endregion}

// === IMPLEMENTATION ===
{region "§1 Gate"}
IF NOT Enable THEN
    SimChainOk     := FALSE;
    SimContactorOk := FALSE;
    SimPhaseRotationOk := FALSE;
    ContactorLatch := FALSE;
    ChainOpen      := TRUE; // Chaîne ouverte par défaut à la ré-entrée (on n'a pas armé)
    ChainOpenReq   := FALSE;
    ContactorEngageReq := FALSE;
    TonChainOpen(IN := FALSE);
    TonChainClose(IN := FALSE);
    TonContactorEngage(IN := FALSE);
    TonContactorDrop(IN := FALSE);
    RETURN;
END_IF;
{endregion}

{region "§2 Chaîne AU (contrôle granulaire + dynamique)"}
// 1. La chaîne AU est saine si l'opérateur la simule fermée (SimChainOkBit = TRUE) ET si aucun
//    événement ne l'ouvre : coup-de-poing (BtnEmergencyStop), test de redondance (TestCutActive),
//    coupure métier (PowerCutOffRequest).
// 🔧 DEADLOCK SIMULATION (corrigé) : la chaîne n'est PAS fermée par défaut ni dépendante de
//    PowerCutOff_A/B (qui sont dans le cercle). Elle est fermée UNIQUEMENT par le bit opérateur
//    `SimChainOkBit`. Le réarmement après échec de test de redondance (RedundancyTestFailedCause laté
//    → PowerCutOff_A=FALSE) reste possible car la chaîne est maintenue fermée par le bit, pas par
//    le PLC. Hors simulation (Enable=FALSE), la chaîne reste pilotée par le matériel via le repli
//    HwReal (PRG_02 §1/§2) — aucune régression sécurité réelle.
// 🆕 DYNAMIQUE : l'ouverture/fermeture suit une temporisation (CST_ChainOpenDelay / CST_ChainCloseDelay)
//    qui simule le temps de retombée des relais AU, tout en restant < 200ms (CST_TestDuration) pour
//    ne pas fausser le test de redondance. Pendant le test, la chaîne clignote (s'ouvre en TEST_A/B,
//    se referme en RESTORE_A/B) puis revient à 1.
ChainOpenReq := (NOT SimChainOkBit) OR BtnEmergencyStop OR TestCutActive OR PowerCutOffRequest;

// Temporisation d'ouverture : la chaîne s'ouvre après CST_ChainOpenDelay de demande soutenue
TonChainOpen(IN := ChainOpenReq, PT := CST_ChainOpenDelay);
// Temporisation de fermeture : la chaîne se ferme après CST_ChainCloseDelay d'absence de demande
TonChainClose(IN := NOT ChainOpenReq, PT := CST_ChainCloseDelay);

// Latch de la chaîne avec temporisations (défaut = ouverte à la ré-entrée)
IF ChainOpenReq THEN
    IF TonChainOpen.Q THEN
        ChainOpen := TRUE;
    END_IF;
ELSE
    IF TonChainClose.Q THEN
        ChainOpen := FALSE;
    END_IF;
END_IF;

SimChainOk := NOT ChainOpen;
{endregion}

{region "§3 Auto-maintien contacteur (dynamique réaliste)"}
// 2. Logique d'auto-maintien (latch) du contacteur avec priorité à la coupure.
// 🆕 DYNAMIQUE : le contacteur ne s'engage QUE pendant l'impulsion d'armement (EmergencyArming)
//    tant que la chaîne est saine, après CST_ContactorEngageDelay (temps de collage bobine), puis
//    s'auto-maintient. Il retombe après CST_ContactorDropDelay (temps de décollage bobine) dès que
//    la chaîne s'ouvre — comme une bobine réelle qui décolle sans alimentation. Ces temporisations
//    restent < CST_ArmingPulseDuration (1s) et CST_ArmingConfirmTimeout (2s) pour que la
//    confirmation contacteur reste validée. À la ré-entrée en simulation, le contacteur est NON
//    engagé (on n'a pas armé).
ContactorEngageReq := EmergencyArming AND SimChainOk;

// Temporisation d'engagement : le contacteur se colle après CST_ContactorEngageDelay de pulse soutenu
TonContactorEngage(IN := ContactorEngageReq, PT := CST_ContactorEngageDelay);
// Temporisation de retombée : le contacteur décolle après CST_ContactorDropDelay de chaîne ouverte
TonContactorDrop(IN := NOT SimChainOk, PT := CST_ContactorDropDelay);

// Latch du contacteur avec priorité à la coupure (retombée > engagement)
IF NOT SimChainOk THEN
    IF TonContactorDrop.Q THEN
        ContactorLatch := FALSE;
    END_IF;
ELSIF ContactorEngageReq THEN
    IF TonContactorEngage.Q THEN
        ContactorLatch := TRUE;
    END_IF;
END_IF;

// Recopie vers la sortie
SimContactorOk := ContactorLatch;

// Contrôleur de phases : simple propagation du bit opérateur (TRUE = sain).
// Inopérant hors simulation (le banc ne publie l'image machine que sous Enable).
SimPhaseRotationOk := SimPhaseRotationOkBit;
{endregion}

instCycleTime(DefaultValueS := 0.010);
(* Le modele mono-pas suit le temps de cycle reel jusqu'a 100 ms. Cette borne
   evite de ralentir artificiellement la dynamique lorsque la trace est executee
   dans VISU_TASK (environ 100 ms), tout en restant stable pour le pendule reduit.
   Au-dela, FB_CycleTime fournit deja son temps de secours et aucun saut aberrant
   n'est accepte. La qualification des delais sub-100 ms exige toutefois une tache
   de trace plus rapide que 100 ms. *)
CycleTimeS := LIMIT(0.001, instCycleTime.CycleTimeS, 0.100);

IF NOT Enable THEN
    Initialized := FALSE;
    instDrive(Enable := FALSE);
    instBrake(Enable := FALSE);
    instSuspendedLoad(Enable := FALSE);
    FrequencyCmd_Hz := 0.0;
    ElectricalFrequency_Hz := 0.0;
    ActualFrequency_Hz := 0.0;
    BrakeMechanicallyOpen := FALSE;
    BrakeContactOpen := FALSE;
    BrakeCoilEnergized := FALSE;
    BrakeFaultCloseActive := FALSE;
    PositionTrue_M := CST_PositionAtP1;
    VelocityTrue_Mps := 0.0;
    PreviousVelocity_Mps := 0.0;
    TravelDirection := 0.0;
    LoadAngle_Rad := 0.0;
    SensorTransitionCount := 0;
    SensorBlipActive := FALSE;
    HardStopTremieActive := FALSE;
    HardStopMaintenanceActive := FALSE;
    (* Repli deterministe compatible avec le mot thermometre P1 = 00011. *)
    PosTremie := FALSE;
    PosPV := FALSE;
    PosP2 := FALSE;
    PosP1 := TRUE;
    PosMaintenance := TRUE;
    instSensorTremie(Enable := FALSE);
    instSensorPV(Enable := FALSE);
    instSensorP2(Enable := FALSE);
    instSensorP1(Enable := FALSE);
    instSensorMaintenance(Enable := FALSE);
    RETURN;
ELSIF NOT Initialized THEN
    Initialized := TRUE;
    PositionTrue_M := CST_PositionAtP1;
    TravelDirection := 0.0;
END_IF;

IF Enable THEN
    DirectionSign := 0.0;
    IF ReqTremie AND NOT ReqMaintenance THEN
        DirectionSign := -1.0;
    ELSIF ReqMaintenance AND NOT ReqTremie THEN
        DirectionSign := 1.0;
    END_IF;

    FrequencyTarget_Hz := LIMIT(0.0, ABS(SpeedTgt_Pct) * 0.4, CST_NominalFrequency_Hz);
    IF DirectionSign = 0.0 THEN
        FrequencyTarget_Hz := 0.0;
    END_IF;
    instDrive(Enable := TRUE, FrequencyTgt_Hz := FrequencyTarget_Hz,
        AccelRate_HzPerS := AccelRate_HzPerS, DecelRate_HzPerS := DecelRate_HzPerS,
        TimeConstant_S := DriveTimeConstantS,
        LoadAngularVelocity_RadPerS := instSuspendedLoad.AngularVelocity_RadPerS,
        LoadFrequencyDroopGain_Hz := LoadFrequencyDroopGain_Hz, CycleTime_S := CycleTimeS);
    FrequencyCmd_Hz := instDrive.FrequencyCmd_Hz;
    ElectricalFrequency_Hz := instDrive.ElectricalFrequency_Hz;
    ActualFrequency_Hz := instDrive.ActualFrequency_Hz;
    instBrake(Enable := TRUE, ReleaseCmd := BrakeReleaseCmd,
        ActualFrequency_Hz := ActualFrequency_Hz, OpenDelay_S := BrakeOpenDelayS,
        CloseDelay_S := BrakeCloseDelayS, ContactDelay_S := BrakeContactDelayS,
        CycleTime_S := CycleTimeS,
        FaultCloseWhileRunning := BrakeFaultCloseWhileRunning,
        FaultCloseDelay_S := BrakeFaultCloseDelay_S);
    BrakeCoilEnergized := instBrake.CoilEnergized;
    BrakeMechanicallyOpen := instBrake.MechanicallyOpen;
    BrakeContactOpen := instBrake.ContactOpen;
    BrakeFaultCloseActive := instBrake.FaultCloseActive;

    (* Sens memorise (C3). Regles, dans cet ordre :
       1. un ordre simple valide (re)memorise le sens ;
       2. deux ordres contradictoires neutralisent immediatement le sens — aucune
          excitation inventee (preserve TC-T300-MEC-030) ;
       3. commande retiree : le sens est CONSERVE tant que le variateur retourne de la
          vitesse (deceleration libre), puis purge des que la vitesse est nulle. *)
    IF ReqTremie AND NOT ReqMaintenance THEN
        TravelDirection := -1.0;
    ELSIF ReqMaintenance AND NOT ReqTremie THEN
        TravelDirection := 1.0;
    ELSIF ReqTremie AND ReqMaintenance THEN
        TravelDirection := 0.0;
    ELSIF ABS(ActualFrequency_Hz) <= CST_StopFrequency_Hz THEN
        TravelDirection := 0.0;
    END_IF;

    PreviousVelocity_Mps := VelocityTrue_Mps;
    IF (FullTravelTimeS > CST_MinTimeS) AND BrakeMechanicallyOpen THEN
        SpeedAt40Hz_Mps := CST_PositionAtMaintenance / FullTravelTimeS;
        VelocityTarget_Mps := TravelDirection * SpeedAt40Hz_Mps * ActualFrequency_Hz / CST_NominalFrequency_Hz;
    ELSE
        VelocityTarget_Mps := 0.0;
    END_IF;
    VelocityTrue_Mps := VelocityTrue_Mps + instDrive.ResponseAlpha * (VelocityTarget_Mps - VelocityTrue_Mps);
    IF NOT BrakeMechanicallyOpen THEN
        VelocityTrue_Mps := 0.0;
    END_IF;
    HardStopTremieActive := FALSE;
    HardStopMaintenanceActive := FALSE;
    PositionCandidate_M := PositionTrue_M + VelocityTrue_Mps * CycleTimeS;
    IF PositionCandidate_M < CST_PositionAtTremie THEN
        PositionTrue_M := CST_PositionAtTremie;
        VelocityTrue_Mps := 0.0;
        HardStopTremieActive := TRUE;
    ELSIF PositionCandidate_M > CST_PositionAtMaintenance THEN
        PositionTrue_M := CST_PositionAtMaintenance;
        VelocityTrue_Mps := 0.0;
        HardStopMaintenanceActive := TRUE;
    END_IF;
    CartAcceleration_Mps2 := (VelocityTrue_Mps - PreviousVelocity_Mps) / CycleTimeS;
    instSuspendedLoad(Enable := TRUE, BrakeMechanicallyOpen := BrakeMechanicallyOpen,
        CartAcceleration_Mps2 := CartAcceleration_Mps2, Length_M := SuspendedLoadLength_M,
        Damping := SuspendedLoadDamping, ReactionGain_Mps2 := LoadReactionGain_Mps2,
        CycleTime_S := CycleTimeS);
    LoadAngle_Rad := instSuspendedLoad.Angle_Rad;
    IF HardStopTremieActive OR HardStopMaintenanceActive THEN
        RecoilMax_M := MIN(MAX(0.0, EndStopRecoilMax_M), CST_PositionAtMaintenance);
        IF (RecoilMax_M > 0.0) AND BrakeMechanicallyOpen THEN
            (* Recul autorise UNIQUEMENT en s'eloignant de la butee touchee, borne par
               EndStopRecoilMax_M : jamais plus loin dans la butee, jamais de saut cache. *)
            VelocityTrue_Mps := VelocityTrue_Mps + instSuspendedLoad.VelocityReaction_Mps;
            (* Contre une butee, l'entrainement DECROCHE : il ne maintient pas une consigne de
               vitesse dans l'obstacle. Sans cette purge, la consigne de vitesse ecrasait en
               permanence la reaction de charge et le chariot ne pouvait jamais ressortir de
               la zone capteur (recul alors impossible, quelle que soit la charge). *)
            TravelDirection := 0.0;
            IF HardStopTremieActive THEN
                VelocityTrue_Mps := MAX(0.0, VelocityTrue_Mps);
                PositionCandidate_M := LIMIT(CST_PositionAtTremie,
                    PositionTrue_M + VelocityTrue_Mps * CycleTimeS,
                    CST_PositionAtTremie + RecoilMax_M);
            ELSE
                VelocityTrue_Mps := MIN(0.0, VelocityTrue_Mps);
                PositionCandidate_M := LIMIT(CST_PositionAtMaintenance - RecoilMax_M,
                    PositionTrue_M + VelocityTrue_Mps * CycleTimeS,
                    CST_PositionAtMaintenance);
            END_IF;
            PositionTrue_M := PositionCandidate_M;
        ELSE
            VelocityTrue_Mps := 0.0;
        END_IF;
    ELSE
        VelocityTrue_Mps := VelocityTrue_Mps + instSuspendedLoad.VelocityReaction_Mps;
        PositionCandidate_M := PositionTrue_M + VelocityTrue_Mps * CycleTimeS;
        IF PositionCandidate_M < CST_PositionAtTremie THEN
            PositionTrue_M := CST_PositionAtTremie;
            VelocityTrue_Mps := 0.0;
            HardStopTremieActive := TRUE;
        ELSIF PositionCandidate_M > CST_PositionAtMaintenance THEN
            PositionTrue_M := CST_PositionAtMaintenance;
            VelocityTrue_Mps := 0.0;
            HardStopMaintenanceActive := TRUE;
        ELSE
            PositionTrue_M := PositionCandidate_M;
        END_IF;
    END_IF;
END_IF;

IF Enable AND (ABS(LoadAngle_Rad) > 0.0001) THEN
    SensorNoiseState := 3.91 * SensorNoiseState * (1.0 - SensorNoiseState);
    SensorNoise_M := (2.0 * SensorNoiseState - 1.0) * SensorJitterAmplitude_M;
ELSE
    SensorNoise_M := 0.0;
END_IF;
(* Les capteurs sont fixes au rail et observent le chariot. Le balancier agit
   seulement par la reaction mecanique sur PositionTrue_M et conditionne un
   episode electrique ; aucune deflexion de godet n'est injectee directement. *)
SensorPosition_M := PositionTrue_M + SensorNoise_M;
(* Les capteurs M3 sont volontairement cumulatifs : 11111 -> 00000. Chaque
   brique garde son hysteresis et son episode propres ; aucun timer partage ne
   peut masquer un front d'un autre capteur. *)
instSensorTremie(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := CST_PositionAtTremieSensor_M, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 11,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);
instSensorPV(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := CST_PositionAtPV, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 23,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);
instSensorP2(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := CST_PositionAtP2, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 37,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);
instSensorP1(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := CST_PositionAtP1, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 53,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);
instSensorMaintenance(Enable := Enable, Position_M := SensorPosition_M,
    Threshold_M := CST_PositionAtMaintenanceSensor_M, Hysteresis_M := SensorHysteresis_M,
    ElectricalDelayS := SensorElectricalDelayS, IntermittenceActive := SensorIntermittenceActive
        AND (ABS(LoadAngle_Rad) >= SensorLoadAngleTriggerRad),
    IntermittenceDurationS := SensorStabilizationS, IntermittencePeriodS := SensorIntermittencePeriodS,
    ScenarioSeed := SensorScenarioSeed + 71,
    BlipTransitions := SensorBlipTransitions, BlipDurationS := SensorBlipDurationS,
    CycleTimeS := CycleTimeS);

PosTremie := instSensorTremie.ElectricalOutput;
PosPV := instSensorPV.ElectricalOutput;
PosP2 := instSensorP2.ElectricalOutput;
PosP1 := instSensorP1.ElectricalOutput;
PosMaintenance := instSensorMaintenance.ElectricalOutput;
SensorTransitionCount := instSensorTremie.TransitionCount + instSensorPV.TransitionCount
    + instSensorP2.TransitionCount + instSensorP1.TransitionCount
    + instSensorMaintenance.TransitionCount;
SensorBlipActive := instSensorTremie.BlipActive OR instSensorPV.BlipActive
    OR instSensorP2.BlipActive OR instSensorP1.BlipActive
    OR instSensorMaintenance.BlipActive;

// === §1 GATE NEUTRALISATION ===
IF NOT Enable THEN
    Ready := FALSE;
    MotorTorque_Nm := 0.0;
    ResistiveTorqueAct_Nm := 0.0;
    Slip_Ratio := 0.0;
    SpeedAct_Rpm := 0.0;
    IsStalled := FALSE;
    IsGeneratorMode := FALSE;
    LoadFracFiltered_Ratio := 0.0;
    RETURN;
END_IF;

// === §2 CHARGE LISSEE (benne au sol force la cible a 0, transition sans a-coup) ===
IF IsBucketGrounded THEN
    LoadFracTarget_Ratio := 0.0;
ELSE
    LoadFracTarget_Ratio := LIMIT(0.0, LoadFrac_Ratio, 1.0);
END_IF;

IF LoadTransitionFilter_S > CST_MinFilterTime_S THEN
    FilterAlpha_Ratio := CycleTime_S / (LoadTransitionFilter_S + CycleTime_S);
ELSE
    FilterAlpha_Ratio := 1.0;
END_IF;
LoadFracFiltered_Ratio := LoadFracFiltered_Ratio
    + FilterAlpha_Ratio * (LoadFracTarget_Ratio - LoadFracFiltered_Ratio);

// === §3 COUPLAGE M1/M2 ===
// En mode couple, la benne lie mecaniquement les deux treuils : un ecart de couple entre pairs
// se traduit en effort differentiel de rattrapage (proportionnel a l'ecart de vitesse), pas en
// deux dynamiques d'inertie totalement independantes qui divergent librement.
IF IsCoupledToPeer THEN
    PeerDifferentialTorque_Nm := CoupledPeerGain_Ratio * (SpeedAct_Rpm - PeerSpeed_Rpm)
        * LoadNominalTorque_Nm / MAX(SynchronousSpeed_Rpm, 1.0);
ELSE
    PeerDifferentialTorque_Nm := 0.0;
END_IF;

// === §4 COUPLE RESISTANT APPLIQUE ===
ResistiveTorqueAct_Nm := LoadFrictionTorque_Nm
    + DirectionCmd * LoadFracFiltered_Ratio * LoadNominalTorque_Nm
    + PeerDifferentialTorque_Nm;

// === §5 MOTEUR ELEMENTAIRE ===
Motor(
    Enable := TRUE,
    StepCmd := StepCmd,
    DirectionCmd := DirectionCmd,
    NetworkVoltageAct_V := NetworkVoltageAct_V,
    ResistiveTorque_Nm := ResistiveTorqueAct_Nm,
    NetworkVoltageNom_V := NetworkVoltageNom_V,
    MaxTorque_Nm := MaxTorque_Nm,
    SlipAtMaxTorqueBase_Ratio := SlipAtMaxTorqueBase_Ratio,
    RotorResistanceOwn_Ohm := RotorResistanceOwn_Ohm,
    Inertia_KgM2 := Inertia_KgM2,
    SynchronousSpeed_Rpm := SynchronousSpeed_Rpm,
    CycleTime_S := CycleTime_S
);

MotorTorque_Nm := Motor.MotorTorque_Nm;
Slip_Ratio := Motor.Slip_Ratio;
SpeedAct_Rpm := Motor.SpeedAct_Rpm;
IsStalled := Motor.IsStalled;
IsGeneratorMode := Motor.IsGeneratorMode;

Ready := TRUE;

{region "§1 Acquisition temps"}
// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();
{endregion}

{region "§2 Initialisation"}
// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;
{endregion}

{region "§3 Calcul delta"}
// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);
{endregion}

{region "§4 Conversion, secours et bornage"}
// 4. CONVERSION EN SECONDES, AVEC DOUBLE BORNAGE DU DELTA
//
// TIME() est un compteur systeme 32 bits en millisecondes depuis le demarrage de
// l'automate. Il n'est PAS absolu : il reboucle a 0 tous les 2^32 ms (~49,7 jours).
// La soustraction TimeCurrent - TimeLast est modulo 2^32 : au passage du rebouclage,
// tant que l'ecart reel entre deux scans reste < 49,7 j (toujours vrai a 10 ms),
// DeltaTimeMs reste correct. Le rebouclage seul n'est donc pas le risque principal.
//
// Le vrai risque est un DeltaTimeMs REELLEMENT > CST_MaxCycleDeltaMs : reprise apres
// un online-change, sortie d'un point d'arret / pas-a-pas debug, ou fenetre du
// rebouclage TIME(). Le chien de garde tache (200 ms, sensibilite 1) borne deja les
// gels en fonctionnement ; ce plafond couvre les cas hors surveillance.
// Un dt aberrant publie tel quel donnerait un CycleTimeS enorme, propage en un seul
// scan dans les rampes de vitesse et les integrateurs de position/frein -> saut
// physique. Fail-safe : hors de la plage nominale (0 < dt <= plafond), on publie la
// valeur de secours DefaultValueS au lieu de l'artefact. Pas de redemarrage auto.
//
// Borne basse dt = 0 (anti-zero, ex. premier appel du scan) et borne haute
// dt > CST_MaxCycleDeltaMs (anti-artefact) partagent la meme branche de secours.
IF (DeltaTimeMs > 0) AND (DeltaTimeMs <= CST_MaxCycleDeltaMs) THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;
{endregion}

{region "§5 Archivage"}
// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;
{endregion}

IF NOT Enable THEN
    Initialized := FALSE;
    RawDetected := FALSE;
    ElectricalOutput := FALSE;
    PreviousRawDetected := FALSE;
    EpisodeActive := FALSE;
    BlipActive := FALSE;
    BlipRunning := FALSE;
    BlipTimerS := 0.0;
    BlipCount := 0;
    DelayTimerS := 0.0;
    EpisodeTimerS := 0.0;
    ToggleTimerS := 0.0;
    TransitionCount := 0;
    EpisodeTogglePeriodS := 0.0;
    RETURN;
END_IF;

(* Hysteresis sur une frontiere cumulative : les cinq DI restent compatibles avec
   le mot thermometre du decodeur M3, contrairement a cinq fenetres independantes. *)
IF NOT Initialized THEN
    IF ActiveBelowThreshold THEN
        RawDetected := Position_M <= Threshold_M;
    ELSE
        RawDetected := Position_M >= Threshold_M;
    END_IF;
    ElectricalOutput := RawDetected;
    PreviousRawDetected := RawDetected;
    RandomState := ScenarioSeed MOD 1000000;
    IF RandomState = 0 THEN
        RandomState := 1;
    END_IF;
    EpisodeTogglePeriodS := MAX(0.01, IntermittencePeriodS);
    Initialized := TRUE;
    RETURN;
END_IF;

IF ActiveBelowThreshold THEN
    IF RawDetected THEN
        RawDetected := Position_M <= (Threshold_M + MAX(0.0, Hysteresis_M));
    ELSE
        RawDetected := Position_M <= (Threshold_M - MAX(0.0, Hysteresis_M));
    END_IF;
ELSE
    IF RawDetected THEN
        RawDetected := Position_M >= (Threshold_M - MAX(0.0, Hysteresis_M));
    ELSE
        RawDetected := Position_M >= (Threshold_M + MAX(0.0, Hysteresis_M));
    END_IF;
END_IF;

(* Un episode est declenche par un franchissement mecanique, pas par une de ses
   propres bascules electriques. Les fronts restent donc bornes et reproductibles. *)
IF RawDetected <> PreviousRawDetected THEN
    PreviousRawDetected := RawDetected;
    EpisodeTarget := RawDetected;
    (* Une bascule mecanique pendant l'episode modifie seulement la cible finale.
       Elle ne remet jamais son chronometre a zero : l'episode reste borne. *)
    IF NOT EpisodeActive THEN
        DelayTimerS := 0.0;
        EpisodeTimerS := 0.0;
        ToggleTimerS := 0.0;
        (* Tirage unique par episode : reproductible pour une graine et sans bruit
           blanc scan-par-scan. La periode varie de 70 % a 130 % du nominal. *)
        RandomState := RandomState + 7919;
        IF RandomState >= 1000000 THEN
            RandomState := RandomState - 1000000;
        END_IF;
        EpisodeTogglePeriodS := MAX(0.01, IntermittencePeriodS
            * (0.7 + UDINT_TO_REAL(RandomState MOD 6000) / 10000.0));
        EpisodeActive := IntermittenceActive AND (IntermittenceDurationS > 0.0);
    END_IF;
    (* Blip court : arme sur le meme front MECANIQUE. Ses propres bascules electriques ne
       peuvent donc jamais le rearmer — meme protection que l'episode d'intermittence. *)
    IF (BlipTransitions > 0) AND (BlipDurationS > 0.0) THEN
        BlipRunning := TRUE;
        BlipTimerS := 0.0;
        BlipCount := 0;
        BlipActive := TRUE;
        (* Ecretage : au-dela de ce plafond, un compteur UDINT pourrait reboucler et rendre
           le blip non terminant (revue du 2026-09-20, F9). *)
        BlipTransitions := MIN(BlipTransitions, CST_BlipMaxTransitions);
    END_IF;
END_IF;

IF BlipRunning THEN
    (* Protocole du blip court : (0) la sortie rejoint d'abord l'etat MECANIQUE — le
       comportement nominal reste donc visible ; puis une excursion contradictoire toutes
       les BlipDurationS, donc de largeur BlipDurationS ; enfin la sortie est rendue a
       l'etat mecanique. Nombre d'excursions = BlipTransitions. *)
    BlipTimerS := BlipTimerS + CycleTimeS;
    IF BlipTimerS >= MAX(CycleTimeS, BlipDurationS) THEN
        BlipTimerS := 0.0;
        IF BlipCount = 0 THEN
            IF ElectricalOutput <> RawDetected THEN
                ElectricalOutput := RawDetected;
                TransitionCount := TransitionCount + 1;
            END_IF;
            BlipCount := 1;
        ELSIF BlipCount <= BlipTransitions THEN
            ElectricalOutput := NOT ElectricalOutput;
            TransitionCount := TransitionCount + 1;
            BlipCount := BlipCount + 1;
        ELSE
            BlipRunning := FALSE;
            BlipActive := FALSE;
            IF ElectricalOutput <> RawDetected THEN
                ElectricalOutput := RawDetected;
                TransitionCount := TransitionCount + 1;
            END_IF;
            DelayTimerS := 0.0;
        END_IF;
    END_IF;
ELSIF EpisodeActive THEN
    EpisodeTimerS := EpisodeTimerS + CycleTimeS;
    ToggleTimerS := ToggleTimerS + CycleTimeS;
    IF ToggleTimerS >= EpisodeTogglePeriodS THEN
        ElectricalOutput := NOT ElectricalOutput;
        ToggleTimerS := 0.0;
        TransitionCount := TransitionCount + 1;
    END_IF;
    IF EpisodeTimerS >= IntermittenceDurationS THEN
        EpisodeActive := FALSE;
        IF ElectricalOutput <> EpisodeTarget THEN
            ElectricalOutput := EpisodeTarget;
            TransitionCount := TransitionCount + 1;
        END_IF;
        DelayTimerS := 0.0;
    END_IF;
ELSIF ElectricalOutput <> RawDetected THEN
    DelayTimerS := DelayTimerS + CycleTimeS;
    IF DelayTimerS >= MAX(0.0, ElectricalDelayS) THEN
        ElectricalOutput := RawDetected;
        DelayTimerS := 0.0;
        TransitionCount := TransitionCount + 1;
    END_IF;
ELSE
    DelayTimerS := 0.0;
END_IF;

IF NOT Enable THEN
    Ready := FALSE;
    Angle_Rad := 0.0;
    AngularVelocity_RadPerS := 0.0;
    VelocityReaction_Mps := 0.0;
    RETURN;
END_IF;

VelocityReaction_Mps := 0.0;
IF Length_M > CST_MinLength_M THEN
    AngularAccel_RadPerS2 := -(CST_Gravity_Mps2 / Length_M) * Angle_Rad
        - MAX(0.0, Damping) * AngularVelocity_RadPerS
        - CartAcceleration_Mps2 / Length_M;
    AngularVelocity_RadPerS := LIMIT(-CST_MaxAngularVelocity_RadPerS,
        AngularVelocity_RadPerS + AngularAccel_RadPerS2 * CycleTime_S, CST_MaxAngularVelocity_RadPerS);
    Angle_Rad := LIMIT(-CST_MaxAngle_Rad, Angle_Rad + AngularVelocity_RadPerS * CycleTime_S,
        CST_MaxAngle_Rad);
    IF BrakeMechanicallyOpen THEN
        VelocityReaction_Mps := ReactionGain_Mps2 * Angle_Rad * CycleTime_S;
    END_IF;
END_IF;
Ready := TRUE;

IF NOT Enable THEN
    Ready := FALSE;
    CoilEnergized := FALSE;
    MechanicallyOpen := FALSE;
    ContactOpen := FALSE;
    FaultCloseActive := FALSE;
    MechanicalTimer_S := 0.0;
    ContactTimer_S := 0.0;
    FaultTimer_S := 0.0;
    RETURN;
END_IF;

(* Faute explicite : chronometre propre, remis a zero des que le stimulus retombe. *)
IF FaultCloseWhileRunning THEN
    FaultTimer_S := FaultTimer_S + CycleTime_S;
ELSE
    FaultTimer_S := 0.0;
END_IF;
FaultCloseActive := FaultCloseWhileRunning AND (FaultTimer_S >= MAX(0.0, FaultCloseDelay_S));

(* La faute fait retomber la bobine : l'etat electrique publie reste coherent avec la
   fermeture mecanique observee (jamais « bobine energisee ET frein serre »). *)
CoilEnergized := ReleaseCmd AND NOT FaultCloseActive;
IF CoilEnergized THEN
    IF NOT MechanicallyOpen THEN
        MechanicalTimer_S := MechanicalTimer_S + CycleTime_S;
        IF MechanicalTimer_S >= MAX(0.0, OpenDelay_S) THEN
            MechanicallyOpen := TRUE;
            MechanicalTimer_S := 0.0;
        END_IF;
    ELSE
        MechanicalTimer_S := 0.0;
    END_IF;
ELSIF FaultCloseActive OR (ActualFrequency_Hz <= CST_StopFrequency_Hz) THEN
    IF MechanicallyOpen THEN
        MechanicalTimer_S := MechanicalTimer_S + CycleTime_S;
        IF MechanicalTimer_S >= MAX(0.0, CloseDelay_S) THEN
            MechanicallyOpen := FALSE;
            MechanicalTimer_S := 0.0;
        END_IF;
    ELSE
        MechanicalTimer_S := 0.0;
    END_IF;
ELSE
    MechanicalTimer_S := 0.0;
END_IF;
IF MechanicallyOpen <> ContactOpen THEN
    ContactTimer_S := ContactTimer_S + CycleTime_S;
    IF ContactTimer_S >= MAX(0.0, ContactDelay_S) THEN
        ContactOpen := MechanicallyOpen;
        ContactTimer_S := 0.0;
    END_IF;
ELSE
    ContactTimer_S := 0.0;
END_IF;
Ready := TRUE;

IF NOT Enable THEN
    Ready := FALSE;
    FrequencyCmd_Hz := 0.0;
    ElectricalFrequency_Hz := 0.0;
    ActualFrequency_Hz := 0.0;
    ResponseAlpha := 0.0;
    RETURN;
END_IF;

FrequencyDelta_Hz := LIMIT(0.0, FrequencyTgt_Hz, CST_MaxFrequency_Hz) - FrequencyCmd_Hz;
IF FrequencyDelta_Hz >= 0.0 THEN
    FrequencyStep_Hz := MAX(0.0, AccelRate_HzPerS) * CycleTime_S;
ELSE
    FrequencyStep_Hz := MAX(0.0, DecelRate_HzPerS) * CycleTime_S;
END_IF;
FrequencyCmd_Hz := FrequencyCmd_Hz + LIMIT(-FrequencyStep_Hz, FrequencyDelta_Hz, FrequencyStep_Hz);
IF TimeConstant_S > CST_MinTime_S THEN
    ResponseAlpha := CycleTime_S / (TimeConstant_S + CycleTime_S);
ELSE
    ResponseAlpha := 1.0;
END_IF;
ElectricalFrequency_Hz := ElectricalFrequency_Hz
    + ResponseAlpha * (FrequencyCmd_Hz - ElectricalFrequency_Hz);
ActualFrequency_Hz := MAX(0.0, ElectricalFrequency_Hz
    - MAX(0.0, LoadFrequencyDroopGain_Hz) * ABS(LoadAngularVelocity_RadPerS));
IF ActualFrequency_Hz < 0.005 THEN
    ActualFrequency_Hz := 0.0;
END_IF;
Ready := TRUE;

// === §1 GATE NEUTRALISATION ===
IF NOT Enable THEN
    Ready := FALSE;
    MotorTorque_Nm := 0.0;
    Slip_Ratio := 0.0;
    SpeedAct_Rpm := 0.0;
    IsStalled := FALSE;
    IsGeneratorMode := FALSE;
    SpeedRel_RadPerS := 0.0;
    RETURN;
END_IF;

StepCmdSafe := LIMIT(1, StepCmd, CST_StepCount);
IF StepCmdSafe <> StepCmd THEN
    Ready := FALSE;
    RETURN;
END_IF;
IF (DirectionCmd <> 1) AND (DirectionCmd <> -1) THEN
    Ready := FALSE;
    RETURN;
END_IF;

// Bornage systematique des entrees de config sensibles (denominateurs) -- CODE_QUALITY_STANDARDS §6
InertiaSafe_KgM2 := MAX(CST_MinDenominator, Inertia_KgM2);
RotorResistanceOwnSafe_Ohm := MAX(CST_MinDenominator, RotorResistanceOwn_Ohm);
SlipAtMaxTorqueBaseSafe_Ratio := MAX(CST_MinDenominator, SlipAtMaxTorqueBase_Ratio);
NetworkVoltageNomSafe_V := MAX(1.0, NetworkVoltageNom_V);

// === §2 GLISSEMENT ET COUPLE (FORMULE DE KLOSS) ===
SynchronousSpeed_RadPerS := SynchronousSpeed_Rpm * 2.0 * 3.14159265 / 60.0;

// gmax(palier) = gmax_base * R2_total(palier) / R2_rotor_propre -- ajouter de la resistance
// externe deplace le glissement au couple max vers 1 (couple demarrage), sans changer Cmax.
// gmax_base = gmax au palier rotor court-circuite (resistance externe nulle).
SlipAtMaxTorqueStep_Ratio := SlipAtMaxTorqueBaseSafe_Ratio
    * (RotorResistanceOwnSafe_Ohm + CST_RotorExtResistanceStep_Ohm[StepCmdSafe])
    / RotorResistanceOwnSafe_Ohm;

// Glissement en repere de commande (N_rel) : peut etre negatif (survitesse -> freinage
// generateur). SpeedRel_RadPerS reste dans ce repere ; SpeedAct_Rpm restitue le signe physique.
Slip_Ratio := 1.0 - SpeedRel_RadPerS / SynchronousSpeed_RadPerS;

IF ABS(Slip_Ratio) < CST_MinSlip_Ratio THEN
    IF Slip_Ratio >= 0.0 THEN
        SlipEff_Ratio := CST_MinSlip_Ratio;
    ELSE
        SlipEff_Ratio := -CST_MinSlip_Ratio;
    END_IF;
ELSE
    SlipEff_Ratio := Slip_Ratio;
END_IF;

VoltageRatio2 := (NetworkVoltageAct_V / NetworkVoltageNomSafe_V) * (NetworkVoltageAct_V / NetworkVoltageNomSafe_V);

KlossRunning(
    Enable := TRUE,
    MaxTorque_Nm := MaxTorque_Nm,
    Slip_Ratio := SlipEff_Ratio,
    SlipAtMaxTorque_Ratio := SlipAtMaxTorqueStep_Ratio,
    VoltageRatio2 := VoltageRatio2);
MotorTorque_Nm := KlossRunning.Torque_Nm;

// === §3 DYNAMIQUE MECANIQUE ===
// Pas de saturation basse : SpeedRel_RadPerS peut devenir negatif (glissement arriere sous
// surcharge) ou depasser le synchronisme (regime generateur).
SpeedRel_RadPerS := SpeedRel_RadPerS
    + (MotorTorque_Nm - ResistiveTorque_Nm) / InertiaSafe_KgM2 * CycleTime_S;

SpeedAct_Rpm := SpeedRel_RadPerS * DirectionCmd * 60.0 / (2.0 * 3.14159265);

// === §4 DECROCHAGE PREDICTIF ===
// Au palier courant, couple disponible a glissement bloque (g=1) < couple resistant, ET
// vitesse quasi nulle -- prediction "ce palier peut-il tenir la charge depuis l'arret ?",
// pas une mesure d'arret reel.
IF ABS(SpeedAct_Rpm) < CST_StallSpeedThreshold_Rpm THEN
    KlossLockedRotor(
        Enable := TRUE,
        MaxTorque_Nm := MaxTorque_Nm,
        Slip_Ratio := 1.0,
        SlipAtMaxTorque_Ratio := SlipAtMaxTorqueStep_Ratio,
        VoltageRatio2 := VoltageRatio2);
    Stalled := KlossLockedRotor.Torque_Nm < ResistiveTorque_Nm;
    IF Stalled THEN
        IsStalled := TRUE;
    END_IF;
ELSE
    Stalled := FALSE;
END_IF;

IsGeneratorMode := MotorTorque_Nm < 0.0;

Ready := TRUE;

IF NOT Enable THEN
    Ready := FALSE;
    Torque_Nm := 0.0;
    RETURN;
END_IF;

Torque_Nm := 2.0 * MaxTorque_Nm
    / (Slip_Ratio / SlipAtMaxTorque_Ratio + SlipAtMaxTorque_Ratio / Slip_Ratio)
    * VoltageRatio2;

Ready := TRUE;
